package savannah.model;

import java.util.List;

import savannah.config.SimulationConfig;

/**
 * Plants can grow, be can be partially eaten, they can be completely eaten and die, plants
 * can spread (the weather effects their ability to spread).
 *
 * @version 26/02/2022
 */
public class Plant extends LivingOrganism
{
    // its current health percentage
    private double healthPercentage;
    // The likelihood a plants being able to spread into areas with no plants
    private double spreadProbability;

    /**
     * Create a new PLANT at location in field.
     * 
     * @param randomHealthPercentage If true, the plant will have a random age.
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Plant(boolean randomHealthPercentage, Field field, Location location) 
    {
        this(randomHealthPercentage, field, location, SimulationConfig.DEFAULT);
    }

    /**
     * Create a new PLANT at location in field.
     * 
     * @param randomHealthPercentage If true, the plant will have a random age.
     * @param field The field currently occupied.
     * @param location The location within the field.
     * @param config Shared simulation configuration.
     */
    public Plant(boolean randomHealthPercentage, Field field, Location location, SimulationConfig config) 
    {
        super(field, location, SpeciesType.PLANT, config);

        foodValue = speciesType.plantConfig(config).foodValue;
        healthPercentage = speciesType.initialPlantHealth(randomHealthPercentage, rand, config);
    }

    /**
     * @Override
     * 
     * This is what the plants does most of the time - it runs 
     * around. Sometimes it will breed or die of old age.
     * 
     * @param newPlants A list to return new Plants.
     */
    public void act(List<LivingOrganism> newPlants)
    {
        incrementAge();
        if(!Time.isNight()) 
        {
            if(isAlive()) 
            {
                spreadProbability = speciesType.getPlantSpreadProbability(Weather.getWeather(), config);

                if (rand.nextDouble() < spreadProbability) 
                {
                    populate(newPlants);
                }
            }
        }
    }

    /**
     * When called, the plant gets eaten and loses a
     * pre-defined amount of health.
     */
    protected int beEaten() 
    {
        healthPercentage -= speciesType.plantConfig(config).percentageEaten;
        if (healthPercentage <= 0)
        {
            setDead();
        }

        return foodValue;
    }

    /**
     * @Override
     *
     * Makes the plant grow to full health.
     */
    protected void incrementAge() 
    {
        healthPercentage += speciesType.plantConfig(config).growthRate;
        if (healthPercentage > 1.0) 
        {
            healthPercentage = 1.0;
        }
    }

    /**
     * @Override
     * 
     * Indicate that the animal is no longer alive.
     * It is removed from the field.
     */
    protected void setDead()
    {
        alive = false;
        if(location != null) 
        {
            field.clear(location, Plant.class);
            location = null;
        }
    }

    /**
     * @Override
     * 
     * Place the plant at the new location in the given field.
     * 
     * @param newLocation The plant's new location.
     */
    protected void setLocation(Location newLocation)
    {
        if(location != null) 
        {
            field.clear(location, Plant.class);
        }

        location = newLocation;
        field.place(this, newLocation);
    }

    /**
     * @Override
     * 
     * Check whether or not this Plant is to give birth at this step.
     * New births will be made into free adjacent locations.
     * 
     * @param newPlants A list to return newly born Plants.
     */
    protected void populate(List<LivingOrganism> newPlants)
    {
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation(), Plant.class);

        // New plants are spread into adjacent locations.
        for(int b = 0; free.size() > 0; b++) 
        {
            newPlants.add(createOffspring(free));
        }
    }

    /**
     * Used to instantiate baby plantlets
     * 
     * @param free List of free locations to spawn
     * @return Returns a new plant object.
     */
    private Plant createOffspring(List<Location> free) 
    {
        Location loc = free.remove(0);
        return speciesType.createPlant(false, field, loc, config);
    }
}

package savannah.engine;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Random;

import savannah.config.SimulationConfig;
import savannah.model.Animal;
import savannah.model.Field;
import savannah.model.LivingOrganism;
import savannah.model.Location;
import savannah.model.Plant;
import savannah.model.Randomizer;
import savannah.model.SpeciesType;
import savannah.model.Time;
import savannah.model.Weather;

/**
 * Owns the simulation state and advances the world one step at a time.
 */
public class SimulationEngine
{
    private final SimulationConfig config;
    private final List<LivingOrganism> animals;
    private final List<LivingOrganism> plants;
    private final Field field;

    public SimulationEngine(int depth, int width, SimulationConfig config)
    {
        this.config = config;

        if(width <= 0 || depth <= 0) {
            System.out.println("The dimensions must be greater than zero.");
            System.out.println("Using default values.");
            depth = config.defaultDepth;
            width = config.defaultWidth;
        }

        animals = new ArrayList<>();
        plants = new ArrayList<>();
        field = new Field(depth, width);
        reset();
    }

    public Field getField()
    {
        return field;
    }

    public int getDepth()
    {
        return field.getDepth();
    }

    public int getWidth()
    {
        return field.getWidth();
    }

    public void reset()
    {
        Time.resetStep();
        animals.clear();
        plants.clear();
        populate();
    }

    public void step()
    {
        Time.incrementStep();
        Weather.updateWeather();

        List<LivingOrganism> newAnimals = new ArrayList<>();
        List<LivingOrganism> newPlants = new ArrayList<>();

        for (Iterator<LivingOrganism> it = animals.iterator(); it.hasNext(); ) {
            Animal animal = (Animal) it.next();
            animal.act(newAnimals);

            if (!animal.isAlive()) {
                it.remove();
            }
        }

        for (Iterator<LivingOrganism> it = plants.iterator(); it.hasNext(); ) {
            Plant plant = (Plant) it.next();
            plant.act(newPlants);

            if (!plant.isAlive()) {
                it.remove();
            }
        }

        animals.addAll(newAnimals);
        plants.addAll(newPlants);
    }

    private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();

        for (int row = 0; row < field.getDepth(); row++) {
            for (int col = 0; col < field.getWidth(); col++) {
                Location location = new Location(row, col);
                plants.add(SpeciesType.PLANT.createPlant(true, field, location, config));

                Animal animal = createInitialAnimal(location, rand);
                if (animal != null) {
                    animals.add(animal);
                }
            }
        }
    }

    private Animal createInitialAnimal(Location location, Random rand)
    {
        if (rand.nextDouble() <= config.lionCreationProbability) {
            return SpeciesType.LION.createAnimal(field, location, true, false, false, config);
        }
        if (rand.nextDouble() <= config.cheetahCreationProbability) {
            return SpeciesType.CHEETAH.createAnimal(field, location, true, false, false, config);
        }
        if (rand.nextDouble() <= config.zebraCreationProbability) {
            return SpeciesType.ZEBRA.createAnimal(field, location, true, false, false, config);
        }
        if (rand.nextDouble() <= config.giraffeCreationProbability) {
            return SpeciesType.GIRAFFE.createAnimal(field, location, true, false, false, config);
        }
        if (rand.nextDouble() <= config.lemurCreationProbability) {
            return SpeciesType.LEMUR.createAnimal(field, location, true, false, false, config);
        }

        return null;
    }
}

