package savannah.model;

import java.util.Iterator;
import java.util.List;

import savannah.config.SimulationConfig;
import savannah.engine.SimulationContext;
/**
 * A class representing shared characteristics of animals.
 *
 * @version 25/02/2022
 */
public abstract class Animal extends LivingOrganism
{
    // Indicates whether an animal is a female or not;
    protected boolean isFemale;    
    // The age at which an animal can start to breed.
    protected int breedingAge;
    // The age to which an animal can live.
    protected int maxAge;
    // The likelihood of an animal breeding.
    protected double breedingProbability;
    // whther the animal is infected or not
    protected boolean infected;
    // The likelihood of an animal having a disease.
    protected double diseaseProbability;
    // The likelihood of an animal catching a disease from another animal
    protected double diseaseSpreadProbability;
    // The likelihood of an animal dying from catching the disease
    protected double deathFromInfectionProbability;
    // The likelihood of an animal becomming immune to the disease
    protected double immuneProbability;
    // whether the animal is immune or not
    protected boolean immune;
    // The maximum number of births.
    protected int maxLitterSize;
    // The animals's age.
    protected int age;
    // The animals's food level, which is increased by eating prey.
    protected int foodLevel;
    // The maximum food level that an animal will eat at. The food level they will stop
    // being hungry at
    protected int maxFoodLevel;
    // Probability that an animal will move at a given step.
    protected double movementProbability;

    /**
     * Create a new animal at location in field.
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     * @param infected Intial state if the animal is infected or not
     * @param immmune Intial state if the animal is immune or not
     */
    public Animal(SimulationContext context, Location location, boolean randomAge, boolean infected, boolean immune, SpeciesType speciesType)
    {
        super(context, location, speciesType);
        this.infected = infected;
        this.immune = immune;

        SimulationConfig config = getConfig();
        SimulationConfig.SpeciesConfig speciesConfig = speciesType.animalConfig(config);
        breedingAge = speciesConfig.breedingAge;
        maxAge = speciesConfig.maxAge;
        breedingProbability = speciesConfig.breedingProbability;
        maxLitterSize = speciesConfig.maxLitterSize;
        maxFoodLevel = speciesConfig.maxFoodLevel;
        foodValue = speciesConfig.foodValue;
        movementProbability = speciesConfig.movementProbability;
        diseaseProbability = config.diseaseProbability;
        diseaseSpreadProbability = config.diseaseSpreadProbability;
        deathFromInfectionProbability = config.deathFromInfectionProbability;
        immuneProbability = config.immuneProbability;

        isFemale = rand.nextBoolean();
        age = speciesType.initialAge(randomAge, rand, config);
        foodLevel = speciesType.initialFoodLevel(randomAge, rand, config);
    }

    /**
     * Create a new animal at location in field.
