    protected void incrementAge()
    {
        age++;
        if(age > maxAge) {
            setDead();
        }
    }

    /**
     * Make this animal's more hungry. This could result in the animal's death.
     */
    protected void incrementHunger()
    {
        foodLevel--;
        if(foodLevel <= 0) {
            setDead();
        }
    }

    /**
     * @Override
     * 
     * New births will be made into free adjacent locations.
     * @param newAnimals A list to return newly born Animals.
     */
    protected void populate(List<LivingOrganism> newAnimals)
    {
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation(), Animal.class);
        //determines the number of offspring the animal will produce

        int births = breed();
        // New animals are born into adjacent locations.

        for(int b = 0; b < births && free.size() > 0; b++) 
        {
            Animal newAnimal = createOffspring(free.remove(0), infected, immune);
            newAnimals.add(newAnimal);
        }
    }

    /**
     * Create an offspring of the current species.
     *
     * @param location The location the offspring should occupy.
     * @param inheritedInfection Whether the offspring inherits infection.
     * @param inheritedImmunity Whether the offspring inherits immunity.
     *
     * @return A new animal of the same species.
     */
    protected Animal createOffspring(Location location, boolean inheritedInfection, boolean inheritedImmunity)
    {
        OffspringHealthState healthState = inheritHealthState(inheritedInfection, inheritedImmunity);
        return speciesType.createAnimal(getContext(), location, false, healthState.isInfected(), healthState.isImmune());
    }

    /**
     * Determine how infection and immunity are inherited by an offspring.
     *
     * @param motherIsInfected Whether the parent is infected.
     * @param motherIsImmune Whether the parent is immune.
     *
     * @return The inherited infection and immunity state.
     */
    protected OffspringHealthState inheritHealthState(boolean motherIsInfected, boolean motherIsImmune)
    {
        boolean offspringIsInfected = motherIsInfected;
        boolean offspringIsImmune = motherIsImmune;

        // If the mother is immune and infected, there is a chance the child gets immunity.
        if (!motherIsImmune && motherIsInfected && rand.nextDouble() < getConfig().offspringImmuneInheritanceProbability) 
        {
            offspringIsImmune = true;
            offspringIsInfected = false;
        }
        // If the mother is immune, there is a chance the child is not immune.
        else if (motherIsImmune && rand.nextDouble() < getConfig().offspringLoseImmunityProbability)
        {
            offspringIsImmune = false;
        }

        return new OffspringHealthState(offspringIsInfected, offspringIsImmune);
    }

    /**
     * Compact state holder for offspring health inheritance.
     */
    protected static final class OffspringHealthState
    {
        private final boolean infected;
        private final boolean immune;

        private OffspringHealthState(boolean infected, boolean immune)
        {
            this.infected = infected;
            this.immune = immune;
        }

        boolean isInfected()
        {
            return infected;
        }

        boolean isImmune()
        {
            return immune;
        }
    }

    /**
     * Generate a number representing the number of births,
     * if it can breed.
     * 
     * @return The number of births (may be zero).
     */
    protected int breed()
    {
        int births = 0;

        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();

        while(it.hasNext()) 
        {
            Location where = it.next();
            Animal animal = (Animal) field.getObjectAt(where, Animal.class);

            // checks to make sure they are of the same species
            if(animal != null && speciesType == animal.getSpeciesType()) 
            {
                //checks to make the other animal is also a male
                if(animal.getIsFemale() == false) 
                {
                    births = rand.nextInt(maxLitterSize) + 1;
                }
            }
        }

        return births;
    }

    /**
     * An Animal can breed if it has reached the breeding age.
     * 
     * @return true if the Animal can breed, false otherwise.
     */
    protected boolean canBreed()
    {
        return age >= breedingAge;
    }

    /**
     * @return Returns the status of the animal being infected or not
     */
    public boolean getIsInfected() 
    {
        return infected;
    }

    /**
     * @return Returns the status of the animal being immune or not
     */
    public boolean getIsImmune() 
    {
        return immune;
    }

    /**
     * Checks all the surroundings to see if there any animals which are infected.
     * 
     * @return Returns true if there is a surrounding animal which is infected.
     */
    protected boolean surroundingsInfected()
    {
        boolean surroundingsAreInfected = false;

        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();

        while(it.hasNext() && ! surroundingsAreInfected) 
        {
            Location where = it.next();
            Animal animal = (Animal) field.getObjectAt(where, Animal.class);

            if (field.getObjectAt(where, Animal.class) != null) 
            {
                if (animal.getIsInfected())
                {
                    surroundingsAreInfected = true;
                }
            }
        }

        return surroundingsAreInfected;
    }
}

